#define L(p,b) length(p - b * clamp(dot(p, b) / dot(b, b), 0., 1. ) ) // draw line

void mainImage( out vec4 O, vec2 u ){
    vec2 U = P(u), D;                               // normalized coordinates        
    float d = 9.;     
    if( T(U).x > 0. )                               // if current cell alive  
        for( int k; k<9; k+= k==3?2:1 ) {           // check neighborhood
            D = vec2(k%3,k/3)-1.;
            if(  T(U+D).x > 0. )                    // if neighborhood alive
             // d = min(d, length(I-U)-1./4. ),
                d = min(d, L( fract(U)-.5, D*4. )); // draw link with center cell
        }
    O = vec4( 1. - S/2.*d );                        // AA draw  
    O.b = T(U).b;                                   // blue = classical cell rendition

 // O = vec4( S*d ); // variant: just do that
}

